labels={142:'Industrial facility with overhead services and marked floor bays',154:'Elevated view of an industrial installation',144:'Completed industrial hall and glazed enclosures',255:'Illuminated restaurant entrance at night',136:'Outdoor refrigeration equipment installation',138:'Standby generator beside an industrial building',117:'Cold room with ceiling-mounted evaporator units',165:'Industrial work area with steel platforms',232:'Ceiling lighting and ventilation fit-out',230:'Restaurant interior with recessed ceiling services',149:'Industrial hall with polished concrete floor',143:'Service corridor and insulated industrial doors',141:'Insulated chambers inside an industrial facility',152:'Overhead view of plant services and access walkways',158:'Industrial mezzanine and service infrastructure',99:'Site team on a prepared construction deck',103:'Reinforcement grid before concrete placement',104:'Concrete placement on a reinforced deck',105:'Site crew inspecting slab reinforcement',107:'Concrete pouring and levelling works',110:'Reinforcement detail around a slab opening',115:'Completed insulated utility building',118:'Electrical meters and distribution panel',121:'Suspended ceiling framework and ventilation services',127:'Reinforced slab and column steelwork',130:'Cable routing beside outdoor equipment',133:'Overhead mechanical services installation',135:'Steel access structure inside an industrial facility',139:'Packaged outdoor mechanical equipment',162:'Stainless steel industrial equipment detail',167:'Precision interior tile installation',171:'Wall tile installation in progress',176:'Floor tiling and finishing work',187:'Exterior paving installation',194:'Completed paved access walkway',195:'Roof surface finishing works',197:'Site crew preparing exterior paving',199:'Block paving installation in progress',207:'Exterior ground preparation and paving works',213:'Night-time crane lift of mechanical equipment',216:'Warehouse aisle and overhead installations',223:'Insulated ventilation duct installation',227:'Concealed ceiling air-conditioning units',234:'Cold-storage shelving and metal floor',237:'Completed insulated chamber with metal flooring',239:'Exterior ventilation ducts and equipment',242:'Colour-coded building services pipework'}
assert len(ids)==90 and len(set(ids))==90
out=Path('assests/gallery'); (out/'full').mkdir(parents=True,exist_ok=True); (out/'thumbs').mkdir(exist_ok=True)
photos=[]; provenance=[]
for n,ident in enumerate(ids,1):
 item=inventory[ident-1]; p=Path(item['path']); im=ImageOps.exif_transpose(Image.open(p)).convert('RGB')
 caption=meta[ident-1]['title'] if ident<=96 else labels[ident]
 name=f'project-{n:03}.webp'; full=im.copy(); full.thumbnail((1600,1600)); full.save(out/'full'/name,'WEBP',quality=86,method=6)
 thumb=im.copy(); thumb.thumbnail((640,640)); thumb.save(out/'thumbs'/name,'WEBP',quality=82,method=6)
 photos.append({'id':n,'src':f'assests/gallery/full/{name}','thumbnail':f'assests/gallery/thumbs/{name}','caption':caption,'width':thumb.width,'height':thumb.height,'sourceLabel':'SPC company profile' if ident<=96 else 'Project image collection'})
 provenance.append({'id':n,'source':str(p),'inventoryId':ident,'sourcePage':meta[ident-1]['source_pdf_page'] if ident<=96 else None})
Path('data/gallery.json').write_text(json.dumps(photos,indent=2),encoding='utf-8')
Path('audit-output/gallery/selection.json').write_text(json.dumps(provenance,indent=2),encoding='utf-8')
print('Selected',len(photos),'images; thumbnails MB',round(sum(p.stat().st_size for p in (out/'thumbs').iterdir())/1e6,2),'full MB',round(sum(p.stat().st_size for p in (out/'full').iterdir())/1e6,2))
